        $this->audit->logFailedAuth('CLAIM_CODE_INVALID', ['claim_code' => $claimCode]);
        throw new InvalidArgumentException('CLAIM_CODE_NOT_FOUND');
    }

    $now = time();

    $this->db->query(
        "SELECT * FROM server_claims WHERE claim_code = :code FOR UPDATE",
