file.content:
.claim-result {
    margin-top: 1rem;
    padding: 0.75rem;
    border-radius: 4px;
    display: none;
}

.claim-result.success {
    display: block;
    background: #dcfce7;
    color: #166534;
    border: 1px solid #86efac;
}

.claim-result.error {
    display: block;
    background: #fee;
    color: #991b1b;
    border: 1px solid #fca5a5;
}

